// Brush coaching index — record JAH-GGN-SMARTTOOTHBRUSH-000001
// Property of Justin Addam Higgins (JAH). Deterministic: same inputs, same output.
var m = {"brush_strokes_min": 62000, "battery_days": 30, "price_usd": 200};
var value = (m.brush_strokes_min*m.battery_days/m.price_usd);
if (!isFinite(value)) { console.log('DEMO_FAIL|JAH-GGN-SMARTTOOTHBRUSH-000001|non-finite'); process.exit(1); }
console.log('DEMO_OK|JAH-GGN-SMARTTOOTHBRUSH-000001|' + value.toFixed(2) + ' coaching index');

